screenPanels.initJs:
function(container, apiUrl, tables) {
  const caseIdInput = container.querySelector('[data-testid="case-id-input"]');
  const appraiserNameInput = container.querySelector('[data-testid="appraiser-name-input"]');
  const logicNameInput = container.querySelector('[data-testid="logic-name-input"]');
  const resultFilter = container.querySelector('[data-testid="result-filter"]');
  const workTypeFilter = container.querySelector('[data-testid="work-type-filter"]');
  const priceRangeFilter = container.querySelector('[data-testid="price-range-filter"]');
  const dateFromInput = container.querySelector('[data-testid="date-from"]');
  const dateToInput = container.querySelector('[data-testid="date-to"]');
  const deviationRangeInput = container.querySelector('[data-testid="deviation-range"]');
  const searchBtn = container.querySelector('[data-testid="search-button"]');
  const resetBtn = container.querySelector('[data-testid="reset-button"]');
  const exportCsvBtn = container.querySelector('[data-testid="export-csv-button"]');
  const historyTbody = container.querySelector('#history-tbody');
  const recordCount = container.querySelector('#record-count');
  const detailPanel = container.querySelector('#detail-panel');
  const closeDetailBtn = container.querySelector('#close-detail');
  const viewFullDetailBtn = container.querySelector('#view-full-detail');
  const exportDetailBtn = container.querySelector('#export-detail');

  let allRecords = [];
  let filteredRecords = [];

  // テーブルインデックス（判定ロジック適用履歴テーブルを想定）
  const tableIndex = 0;

  // 初期データ取得
  async function loadData() {
    const records = await window.aivicApi.list(tableIndex);
    if (records) {
      allRecords = records;
      filteredRecords = records;
      renderTable(filteredRecords);
    }
  }

  // テーブル描画
  function renderTable(records) {
    historyTbody.innerHTML = '';
    records.forEach((record, idx) => {
      const row = document.createElement('tr');
      row.style.cssText = 'cursor: pointer; border-bottom: 1px solid var(--border);';
      row.style.backgroundColor = idx % 2 === 0 ? 'var(--bg-card)' : 'rgba(0,0,0,0.02)';
      row.onmouseover = () => row.style.backgroundColor = 'rgba(0,0,0,0.04)';
      row.onmouseout = () => row.style.backgroundColor = idx % 2 === 0 ? 'var(--bg-card)' : 'rgba(0,0,0,0.02)';
      row.onclick = () => showDetail(record);

      const caseId = record.case_id || record.査定案件ID || '—';
      const appraiserName = record.appraiser_name || record.査定員名 || '—';
      const logicName = record.logic_name || record.ロジック名 || '—';
      const appliedAt = record.applied_at || record.適用日時 || '—';
      const result = record.result || record.判定結果 || '—';
      const deviation = record.deviation_rate || record.乖離率 || '—';

      row.innerHTML = `
        <td style="padding: 8px 12px; border-right: 1px solid var(--border); color: var(--text);">${caseId}</td>
        <td style="padding: 8px 12px; border-right: 1px solid var(--border); color: var(--text);">${appraiserName}</td>
        <td style="padding: 8px 12px; border-right: 1px solid var(--border); color: var(--text);">${logicName}</td>
        <td style="padding: 8px 12px; border-right: 1px solid var(--border); color: var(--text); font-size: 12px;">${appliedAt}</td>
        <td style="padding: 8px 12px; border-right: 1px solid var(--border); text-align: center; color: var(--text);">
          <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; background: ${getResultBgColor(result)}; color: #fff; font-size: 11px; font-weight: 500;">${result}</span>
        </td>
        <td style="padding: 8px 12px; text-align: center; color: var(--text);">${deviation}</td>
      `;
      historyTbody.appendChild(row);
    });
    recordCount.textContent = records.length;
  }

  // 判定結果に応じた背景色
  function getResultBgColor(result) {
    switch (result) {
      case '合格': return '#48bb78';
      case '不合格': return '#f56565';
      case '条件付き合格': return '#ed8936';
      case '保留': return '#a0aec0';
      default: return '#718096';
    }
  }

  // 詳細パネル表示
  function showDetail(record) {
    const detailContent = container.querySelector('#detail-content');
    const reasonContent = container.querySelector('#reason-content');
    const conditionContent = container.querySelector('#condition-content');

    // 基本情報
    detailContent.innerHTML = `
      <div style="margin-bottom: 8px;">
        <span style="color: var(--text-muted); font-weight: 500;">案件ID:</span>
        <span style="color: var(--text);">${record.case_id || record.査定案件ID || '—'}</span>
      </div>
      <div style="margin-bottom: 8px;">
        <span style="color: var(--text-muted); font-weight: 500;">査定員:</span>
        <span style="color: var(--text);">${record.appraiser_name || record.査定員名 || '—'}</span>
      </div>
      <div style="margin-bottom: 8px;">
        <span style="color: var(--text-muted); font-weight: 500;">ロジック:</span>
        <span style="color: var(--text);">${record.logic_name || record.ロジック名 || '—'}</span>
      </div>
      <div style="margin-bottom: 8px;">
        <span style="color: var(--text-muted); font-weight: 500;">適用日時:</span>
        <span style="color: var(--text);">${record.applied_at || record.適用日時 || '—'}</span>
      </div>
      <div style="margin-bottom: 8px;">
        <span style="color: var(--text-muted); font-weight: 500;">判定結果:</span>
        <span style="color: var(--text);">${record.result || record.判定結果 || '—'}</span>
      </div>
      <div style="margin-bottom: 8px;">
        <span style="color: var(--text-muted); font-weight: 500;">査定金額:</span>
        <span style="color: var(--text);">¥${(record.assessment_amount || record.査定金額 || 0).toLocaleString()}</span>
      </div>
      <div style="margin-bottom: 8px;">
        <span style="color: var(--text-muted); font-weight: 500;">相場金額:</span>
        <span style="color: var(--text);">¥${(record.market_price || record.相場金額 || 0).toLocaleString()}</span>
      </div>
      <div style="margin-bottom: 8px;">
        <span style="color: var(--text-muted); font-weight: 500;">乖離率:</span>
        <span style="color: var(--text);">${record.deviation_rate || record.乖離率 || '—'}</span>
      </div>
    `;

    // 判定根拠
    reasonContent.textContent = record.reason || record.判定理由 || '根拠情報なし';

    // 適用条件
    conditionContent.innerHTML = `
      <div style="margin-bottom: 6px;"><strong>工種:</strong> ${record.work_type || record.工種 || '—'}</div>
      <div style="margin-bottom: 6px;"><strong>金額帯:</strong> ${record.price_range || record.金額帯 || '—'}</div>
      <div style="margin-bottom: 6px;"><strong>適用ステータス:</strong> ${record.status || record.適用ステータス || '—'}</div>
      <div style="margin-bottom: 6px;"><strong>自動適用:</strong> ${record.auto_applied ? 'はい' : 'いいえ'}</div>
    `;

    detailPanel.style.display = 'block';
  }

  // 詳細パネル閉じる
  closeDetailBtn.onclick = () => {
    detailPanel.style.display = 'none';
  };

  // 検索実行
  searchBtn.onclick = () => {
    const caseId = caseIdInput.value.toLowerCase();
    const appraiserName = appraiserNameInput.value.toLowerCase();
    const logicName = logicNameInput.value.toLowerCase();
    const result = resultFilter.value;
    const workType = workTypeFilter.value;
    const priceRange = priceRangeFilter.value;
    const dateFrom = dateFromInput.value;
    const dateTo = dateToInput.value;
    const deviationRange = deviationRangeInput.value;

    filteredRecords = allRecords.filter(record => {
      const recordCaseId = (record.case_id || record.査定案件ID || '').toLowerCase();
      const recordAppraiserName = (record.appraiser_name || record.査定員名 || '').toLowerCase();
      const recordLogicName = (record.logic_name || record.ロジック名 || '').toLowerCase();
      const recordResult = record.result || record.判定結果 || '';
      const recordWorkType = record.work_type || record.工種 || '';
      const recordPriceRange = record.price_range || record.金額帯 || '';
      const recordAppliedAt = record.applied_at || record.適用日時 || '';

      let match = true;
      if (caseId && !recordCaseId.includes(caseId)) match = false;
      if (appraiserName && !recordAppraiserName.includes(appraiserName)) match = false;
      if (logicName && !recordLogicName.includes(logicName)) match = false;
      if (result && recordResult !== result) match = false;
      if (workType && recordWorkType !== workType) match = false;
      if (priceRange && recordPriceRange !== priceRange) match = false;
      if (dateFrom && recordAppliedAt < dateFrom) match = false;
      if (dateTo && recordAppliedAt > dateTo) match = false;

      return match;
    });

    renderTable(filteredRecords);
  };

  // リセット
  resetBtn.onclick = () => {
    caseIdInput.value = '';
    appraiserNameInput.value = '';
    logicNameInput.value = '';
    resultFilter.value = '';
    workTypeFilter.value = '';
    priceRangeFilter.value = '';
    dateFromInput.value = '';
    dateToInput.value = '';
    deviationRangeInput.value = '';
    filteredRecords = allRecords;
    renderTable(filteredRecords);
  };

  // CSVエクスポート
  exportCsvBtn.onclick = () => {
    const headers = ['案件ID', '査定員名', 'ロジック名', '適用日時', '判定結果', '査定金額', '相場金額', '乖離率'];
    const rows = filteredRecords.map(r => [
      r.case_id || r.査定案件ID || '',
      r.appraiser_name || r.査定員名 || '',
      r.logic_name || r.ロジック名 || '',
      r.applied_at || r.適用日時 || '',
      r.result || r.判定結果 || '',
      r.assessment_amount || r.査定金額 || '',
      r.market_price || r.相場金額 || '',
      r.deviation_rate || r.乖離率 || ''
    ]);

    const csv = '\uFEFF' + [headers, ...rows].map(row =>
      row.map(cell => {
        const str = String(cell);
        return str.includes(',') || str.includes('"') || str.includes('\n')
          ? `"${str.replace(/"/g, '""')}"` : str;
      }).join(',')
    ).join('\n');

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = 'logic_history_' + new Date().toISOString().split('T')[0] + '.csv';
    link.click();
  };

  // 詳細表示ボタン
  viewFullDetailBtn.onclick = () => {
    window.showScreen('scr-1783331002299');
  };

  // PDF出力ボタン
  exportDetailBtn.onclick = () => {
    alert('PDF出力機能は準備中です');
  };

  // 初期ロード
  loadData();
}

function(container, apiUrl, tables) {
  const assessorSelect = container.querySelector('[data-testid="assessor-select"]');
  const startDateInput = container.querySelector('[data-testid="start-date"]');
  const endDateInput = container.querySelector('[data-testid="end-date"]');
  const workTypeSelect = container.querySelector('[data-testid="work-type-select"]');
  const priceRangeSelect = container.querySelector('[data-testid="price-range-select"]');
  const searchBtn = container.querySelector('[data-testid="search-button"]');
  const resetBtn = container.querySelector('[data-testid="reset-button"]');
  const exportBtn = container.querySelector('[data-testid="export-csv-button"]');
  const detailBtn = container.querySelector('[data-testid="detail-analysis-button"]');

  // グラフ描画用
  const deviationChartCanvas = container.querySelector('#deviation-chart');
  const accuracyTrendCanvas = container.querySelector('#accuracy-trend-chart');

  // 初期化：グラフ描画
  function drawDeviationChart() {
    const ctx = deviationChartCanvas.getContext('2d');
    const width = deviationChartCanvas.width;
    const height = deviationChartCanvas.height;
    ctx.clearRect(0, 0, width, height);

    // 簡易ヒストグラム（乖離率分布）
    const data = [12, 28, 45, 38, 22, 8];
    const labels = ['-10%', '-5%', '0%', '+5%', '+10%', '+15%'];
    const barWidth = width / data.length;
    const maxValue = Math.max(...data);

    ctx.fillStyle = '#4a5568';
    ctx.font = '11px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillStyle = '#718096';

    for (let i = 0; i < data.length; i++) {
      const barHeight = (data[i] / maxValue) * (height - 30);
      const x = i * barWidth + barWidth / 2;
      const y = height - 20 - barHeight;

      ctx.fillStyle = '#4a5568';
      ctx.fillRect(x - barWidth / 3, y, barWidth * 0.6, barHeight);

      ctx.fillStyle = '#718096';
      ctx.fillText(labels[i], x, height - 5);
    }
  }

  function drawAccuracyTrendChart() {
    const ctx = accuracyTrendCanvas.getContext('2d');
    const width = accuracyTrendCanvas.width;
    const height = accuracyTrendCanvas.height;
    ctx.clearRect(0, 0, width, height);

    // 簡易折れ線グラフ（月次精度推移）
    const data = [85, 87, 89, 91, 92, 92.5];
    const months = ['6月', '7月', '8月', '9月', '10月', '11月'];
    const pointSpacing = width / (data.length - 1);
    const minValue = 80;
    const maxValue = 100;
    const range = maxValue - minValue;

    ctx.strokeStyle = '#4a5568';
    ctx.lineWidth = 2;
    ctx.beginPath();

    for (let i = 0; i < data.length; i++) {
      const x = i * pointSpacing;
      const y = height - 30 - ((data[i] - minValue) / range) * (height - 50);

      if (i === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    }
    ctx.stroke();

    // ポイント描画
    ctx.fillStyle = '#4a5568';
    for (let i = 0; i < data.length; i++) {
      const x = i * pointSpacing;
      const y = height - 30 - ((data[i] - minValue) / range) * (height - 50);
      ctx.beginPath();
      ctx.arc(x, y, 3, 0, Math.PI * 2);
      ctx.fill();
    }

    // 月ラベル
    ctx.fillStyle = '#718096';
    ctx.font = '11px sans-serif';
    ctx.textAlign = 'center';
    for (let i = 0; i < months.length; i++) {
      const x = i * pointSpacing;
      ctx.fillText(months[i], x, height - 5);
    }
  }

  // 検索処理
  searchBtn.addEventListener('click', async () => {
    const assessorId = assessorSelect.value;
    const startDate = startDateInput.value;
    const endDate = endDateInput.value;
    const workType = workTypeSelect.value;
    const priceRange = priceRangeSelect.value;

    // フィルター条件でデータ再取得・再描画
    drawDeviationChart();
    drawAccuracyTrendChart();
  });

  // リセット処理
  resetBtn.addEventListener('click', () => {
    assessorSelect.value = '';
    startDateInput.value = '';
    endDateInput.value = '';
    workTypeSelect.value = '';
    priceRangeSelect.value = '';
    drawDeviationChart();
    drawAccuracyTrendChart();
  });

  // CSVエクスポート
  exportBtn.addEventListener('click', async () => {
    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    const headers = ['案件ID', '査定員', '査定金額', '相場金額', '乖離率', '分類', '品質判定'];
    const csvContent = [
      '\uFEFF' + headers.join(','),
      ...rows.map(r => [r.projectId, r.assessor, r.assessmentAmount, r.marketAmount, r.deviationRate, r.classification, r.qualityJudgment].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = 'deviation-analysis.csv';
    link.click();
  });

  // 詳細分析へ遷移
  detailBtn.addEventListener('click', () => {
    window.showScreen('scr-1783330955923');
  });

  // 初期描画
  drawDeviationChart();
  drawAccuracyTrendChart();
}

function(container, apiUrl, tables) {
  const resultTbody = container.querySelector('#result-tbody');
  const deviationTbody = container.querySelector('#deviation-tbody');
  const saveDialog = container.querySelector('#save-dialog');
  const detailPanel = container.querySelector('#detail-panel');
  const recordStatus = container.querySelector('#record-status');
  const timestamp = container.querySelector('#timestamp');

  // 初期データロード
  async function loadData() {
    try {
      // 査定判定結果一覧
      const results = await window.aivicApi.list(2); // 査定判定結果テーブル
      if (results && results.length > 0) {
        resultTbody.innerHTML = results.slice(0, 10).map(r => `
          <tr>
            <td style="padding: 6px 8px; border-bottom: 1px solid var(--border);">${r.id?.substring(0, 8) || '案件-001'}</td>
            <td style="padding: 6px 8px; border-bottom: 1px solid var(--border);">${r.査定対象品名 || '商品'}</td>
            <td style="padding: 6px 8px; border-bottom: 1px solid var(--border);">査定員A</td>
            <td style="padding: 6px 8px; border-bottom: 1px solid var(--border); text-align: right;">¥${(r.査定額 || 0).toLocaleString()}</td>
            <td style="padding: 6px 8px; border-bottom: 1px solid var(--border); text-align: right;">¥830,000</td>
            <td style="padding: 6px 8px; border-bottom: 1px solid var(--border); text-align: right; color: #d97706;">+2.4%</td>
            <td style="padding: 6px 8px; border-bottom: 1px solid var(--border); text-align: center;">
              <button class="detail-btn" data-id="${r.id}" style="padding: 3px 8px; background: transparent; color: var(--primary); border: 1px solid var(--primary); border-radius: 2px; font-size: 11px; cursor: pointer;">詳細</button>
            </td>
          </tr>
        `).join('');
      }

      // 乖離パターン履歴
      const deviations = await window.aivicApi.list(11); // 乖離パターン履歴テーブル
      if (deviations && deviations.length > 0) {
        deviationTbody.innerHTML = deviations.slice(0, 5).map(d => `
          <tr>
            <td style="padding: 6px 8px; border-bottom: 1px solid var(--border);">2024-01-15 10:30</td>
            <td style="padding: 6px 8px; border-bottom: 1px solid var(--border);">${d.乖離パターン分類 || '高評価乖離'}</td>
            <td style="padding: 6px 8px; border-bottom: 1px solid var(--border); text-align: right;">+${d.乖離率 || 4.5}%</td>
            <td style="padding: 6px 8px; border-bottom: 1px solid var(--border);">${d.乖離要因 || '希少品'}</td>
          </tr>
        `).join('');
      }
    } catch (e) {
      console.error('データロード失敗:', e);
    }
  }

  // 検索処理
  container.querySelector('[data-testid="search-button"]').addEventListener('click', async () => {
    const caseSearch = container.querySelector('[data-testid="case-search"]').value;
    const assessor = container.querySelector('[data-testid="assessor-select"]').value;
    console.log('検索:', { caseSearch, assessor });
    await loadData();
  });

  // 詳細ボタン
  container.addEventListener('click', (e) => {
    if (e.target.classList.contains('detail-btn')) {
      const id = e.target.dataset.id;
      container.querySelector('#detail-case-id').textContent = id?.substring(0, 8) || '案件-001';
      detailPanel.style.display = 'flex';
    }
  });

  // 詳細パネル閉じる
  container.querySelector('[data-testid="detail-close"]').addEventListener('click', () => {
    detailPanel.style.display = 'none';
  });

  // 保存ボタン
  container.querySelector('[data-testid="save-button"]').addEventListener('click', () => {
    saveDialog.style.display = 'flex';
  });

  // 保存確認ダイアログ
  container.querySelector('[data-testid="dialog-cancel"]').addEventListener('click', () => {
    saveDialog.style.display = 'none';
  });

  container.querySelector('[data-testid="dialog-confirm"]').addEventListener('click', async () => {
    try {
      const now = new Date().toLocaleString('ja-JP');
      recordStatus.textContent = `記録ステータス: 保存完了 (${now})`;
      timestamp.textContent = `最終更新: ${now}`;
      saveDialog.style.display = 'none';
      console.log('根拠記録を保存しました');
    } catch (e) {
      console.error('保存失敗:', e);
    }
  });

  // キャンセルボタン
  container.querySelector('[data-testid="cancel-button"]').addEventListener('click', () => {
    recordStatus.textContent = '記録ステータス: 未保存';
  });

  // CSVエクスポート
  container.querySelector('[data-testid="export-button"]').addEventListener('click', async () => {
    try {
      const results = await window.aivicApi.list(2);
      if (!results || results.length === 0) return;

      const headers = ['案件ID', '品名', '査定員', '査定額', '相場額', '乖離率'];
      const rows = results.map(r => [
        r.id?.substring(0, 8) || '',
        r.査定対象品名 || '',
        '査定員A',
        r.査定額 || '',
        '830000',
        '2.4'
      ]);

      const csv = '\uFEFF' + [headers, ...rows].map(r => r.map(v => `"${v}"`).join(',')).join('\n');
      const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `根拠記録_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    } catch (e) {
      console.error('エクスポート失敗:', e);
    }
  });

  // 初期化
  loadData();
}

function(container, apiUrl, tables) {
  const statusFilterEl = container.querySelector('[data-testid="status-filter"]');
  const priorityFilterEl = container.querySelector('[data-testid="priority-filter"]');
  const searchBtn = container.querySelector('[data-testid="search-button"]');
  const exportBtn = container.querySelector('[data-testid="export-button"]');
  const proposalTbody = container.querySelector('#proposal-tbody');
  const detailPanel = container.querySelector('#detail-panel');
  const closeDetailBtn = container.querySelector('#close-detail');
  const detailPrioritySelect = container.querySelector('#detail-priority');
  const detailStatusSelect = container.querySelector('#detail-status');
  const saveDetailBtn = container.querySelector('#save-detail');

  let allProposals = [];
  let selectedProposal = null;

  // テーブルインデックス（改善提案テーブルと仮定）
  const tableIndex = 0;

  // 初期データ取得
  async function loadProposals() {
    const data = await window.aivicApi.list(tableIndex);
    if (data) {
      allProposals = data;
      renderTable(allProposals);
    }
  }

  // テーブル描画
  function renderTable(proposals) {
    proposalTbody.innerHTML = '';
    proposals.forEach(proposal => {
      const row = document.createElement('tr');
      row.style.cssText = 'border-bottom: 1px solid var(--border); cursor: pointer; transition: background 0.2s;';
      row.dataset.id = proposal.id;

      const priorityColor = proposal.優先度レベル === '高' ? '#d32f2f' : proposal.優先度レベル === '中' ? '#f57c00' : '#1976d2';
      const statusBg = proposal.承認ステータス === '承認済み' ? '#4caf50' : proposal.承認ステータス === '却下' ? '#d32f2f' : '#ff9800';

      row.innerHTML = `
        <td style="padding: 8px 10px; border-right: 1px solid var(--border); color: var(--text);">${proposal.提案ID || '-'}</td>
        <td style="padding: 8px 10px; border-right: 1px solid var(--border); color: var(--text);">${proposal.提案者名 || '-'}</td>
        <td style="padding: 8px 10px; border-right: 1px solid var(--border); color: var(--text); max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${proposal.提案内容 || '-'}</td>
        <td style="padding: 8px 10px; border-right: 1px solid var(--border); text-align: center;">
          <span style="display: inline-block; padding: 3px 8px; background: ${priorityColor}; color: #fff; border-radius: 3px; font-size: 11px; font-weight: 600;">${proposal.優先度レベル || '-'}</span>
        </td>
        <td style="padding: 8px 10px; text-align: center;">
          <span style="display: inline-block; padding: 3px 8px; background: ${statusBg}; color: #fff; border-radius: 3px; font-size: 11px; font-weight: 600;">${proposal.承認ステータス || '-'}</span>
        </td>
      `;

      row.addEventListener('click', () => showDetail(proposal));
      row.addEventListener('mouseenter', () => row.style.background = 'var(--bg-main)');
      row.addEventListener('mouseleave', () => row.style.background = 'transparent');

      proposalTbody.appendChild(row);
    });
  }

  // 詳細パネル表示
  function showDetail(proposal) {
    selectedProposal = proposal;
    container.querySelector('#detail-id').textContent = proposal.提案ID || '-';
    container.querySelector('#detail-proposer').textContent = proposal.提案者名 || '-';
    container.querySelector('#detail-date').textContent = proposal.提案日時 ? new Date(proposal.提案日時).toLocaleString('ja-JP') : '-';
    container.querySelector('#detail-content').textContent = proposal.提案内容 || '-';
    container.querySelector('#detail-impact').textContent = proposal.影響度スコア ? `${proposal.影響度スコア}/100` : '-';
    container.querySelector('#detail-difficulty').textContent = proposal.実装難度 || '-';
    container.querySelector('#detail-effect').textContent = proposal.期待効果 || '-';

    detailPrioritySelect.value = proposal.優先度レベル || '';
    detailStatusSelect.value = proposal.承認ステータス || '';

    detailPanel.style.display = 'flex';
  }

  // 詳細パネル閉じる
  closeDetailBtn.addEventListener('click', () => {
    detailPanel.style.display = 'none';
    selectedProposal = null;
  });

  // 詳細情報保存
  saveDetailBtn.addEventListener('click', async () => {
    if (!selectedProposal) return;

    const updated = await window.aivicApi.update(tableIndex, selectedProposal.id, {
      優先度レベル: detailPrioritySelect.value,
      承認ステータス: detailStatusSelect.value
    });

    if (updated) {
      selectedProposal.優先度レベル = detailPrioritySelect.value;
      selectedProposal.承認ステータス = detailStatusSelect.value;
      renderTable(allProposals);
      detailPanel.style.display = 'none';
      selectedProposal = null;
    }
  });

  // 検索フィルタ
  searchBtn.addEventListener('click', () => {
    const statusFilter = statusFilterEl.value;
    const priorityFilter = priorityFilterEl.value;

    const filtered = allProposals.filter(p => {
      const statusMatch = !statusFilter || p.承認ステータス === statusFilter;
      const priorityMatch = !priorityFilter || p.優先度レベル === priorityFilter;
      return statusMatch && priorityMatch;
    });

    renderTable(filtered);
  });

  // CSVエクスポート
  exportBtn.addEventListener('click', async () => {
    const data = await window.aivicApi.list(tableIndex);
    if (!data || data.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['提案ID', '提案者名', '提案内容', '提案日時', '承認ステータス', '優先度レベル', '影響度スコア', '実装難度', '期待効果'];
    const rows = data.map(p => [
      p.提案ID || '',
      p.提案者名 || '',
      p.提案内容 || '',
      p.提案日時 ? new Date(p.提案日時).toLocaleString('ja-JP') : '',
      p.承認ステータス || '',
      p.優先度レベル || '',
      p.影響度スコア || '',
      p.実装難度 || '',
      p.期待効果 || ''
    ]);

    const csv = '\uFEFF' + headers.join(',') + '\n' + rows.map(r => r.map(cell => {
      const escaped = String(cell).replace(/"/g, '""');
      return escaped.includes(',') || escaped.includes('"') || escaped.includes('\n') ? `"${escaped}"` : escaped;
    }).join(',')).join('\n');

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `改善提案_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 初期ロード
  loadProposals();
}

function(container, apiUrl, tables) {
  const monthInput = container.querySelector('[data-testid="month-input"]');
  const appraiserSelect = container.querySelector('[data-testid="appraiser-select"]');
  const totalCasesInput = container.querySelector('[data-testid="total-cases-input"]');
  const completedCasesInput = container.querySelector('[data-testid="completed-cases-input"]');
  const avgTimeInput = container.querySelector('[data-testid="avg-time-input"]');
  const accuracyScoreInput = container.querySelector('[data-testid="accuracy-score-input"]');
  const deviationRateInput = container.querySelector('[data-testid="deviation-rate-input"]');
  const varianceIndexInput = container.querySelector('[data-testid="variance-index-input"]');
  const deviationPatternSelect = container.querySelector('[data-testid="deviation-pattern-select"]');
  const logicApplyCountInput = container.querySelector('[data-testid="logic-apply-count-input"]');
  const remarksTextarea = container.querySelector('[data-testid="remarks-textarea"]');
  const saveButton = container.querySelector('[data-testid="save-button"]');
  const cancelButton = container.querySelector('[data-testid="cancel-button"]');

  // 当月をデフォルト設定
  const today = new Date();
  const currentMonth = today.toISOString().slice(0, 7);
  monthInput.value = currentMonth;

  // 保存処理
  saveButton.addEventListener('click', async () => {
    const formData = {
      year_month: monthInput.value,
      appraiser_id: appraiserSelect.value,
      total_cases: parseInt(totalCasesInput.value) || 0,
      completed_cases: parseInt(completedCasesInput.value) || 0,
      avg_appraisal_time: parseFloat(avgTimeInput.value) || 0,
      accuracy_score: parseFloat(accuracyScoreInput.value) || 0,
      deviation_rate: parseFloat(deviationRateInput.value) || 0,
      variance_index: parseFloat(varianceIndexInput.value) || 0,
      deviation_pattern: deviationPatternSelect.value,
      logic_apply_count: parseInt(logicApplyCountInput.value) || 0,
      remarks: remarksTextarea.value
    };

    if (!formData.year_month || !formData.appraiser_id) {
      alert('年月と査定員を選択してください');
      return;
    }

    const saved = await window.aivicApi.save(0, formData);
    if (saved) {
      alert('月次実績データを保存しました');
      // フォームをリセット
      monthInput.value = currentMonth;
      appraiserSelect.value = '';
      totalCasesInput.value = '';
      completedCasesInput.value = '';
      avgTimeInput.value = '';
      accuracyScoreInput.value = '';
      deviationRateInput.value = '';
      varianceIndexInput.value = '';
      deviationPatternSelect.value = '';
      logicApplyCountInput.value = '';
      remarksTextarea.value = '';
    }
  });

  // キャンセル処理
  cancelButton.addEventListener('click', () => {
    if (confirm('入力内容を破棄してもよろしいですか？')) {
      monthInput.value = currentMonth;
      appraiserSelect.value = '';
      totalCasesInput.value = '';
      completedCasesInput.value = '';
      avgTimeInput.value = '';
      accuracyScoreInput.value = '';
      deviationRateInput.value = '';
      varianceIndexInput.value = '';
      deviationPatternSelect.value = '';
      logicApplyCountInput.value = '';
      remarksTextarea.value = '';
    }
  });

  // フォーカス時のスタイル設定
  [monthInput, appraiserSelect, totalCasesInput, completedCasesInput, avgTimeInput, accuracyScoreInput, deviationRateInput, varianceIndexInput, deviationPatternSelect, logicApplyCountInput, remarksTextarea].forEach(el => {
    el.addEventListener('focus', function() {
      this.style.borderColor = 'var(--primary)';
      this.style.boxShadow = '0 0 0 2px rgba(74, 85, 104, 0.08)';
    });
    el.addEventListener('blur', function() {
      this.style.borderColor = 'rgba(255,255,255,0.18)';
      this.style.boxShadow = 'none';
    });
  });
}
